mapper.select:
SELECT COUNT(*) AS total_reservation_count, SUM(CASE WHEN reservation_status = 'PENDING' THEN 1 ELSE 0 END) AS pending_count, SUM(CASE WHEN reservation_status = 'CONFIRMED' THEN 1 ELSE 0 END) AS confirmed_count, SUM(CASE WHEN reservation_status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_count, SUM(CASE WHEN reservation_status = 'CANCELED' THEN 1 ELSE 0 END) AS canceled_count, SUM(CASE WHEN reservation_status = 'NO_SHOW' THEN 1 ELSE 0 END) AS no_show_count, CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND((SUM(CASE WHEN reservation_status = 'NO_SHOW' THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)) * 100, 2) END AS no_show_rate FROM reservation WHERE 1 = 1
AND reservation_date >= #{startDate}
AND reservation_date <= #{endDate}

SELECT COUNT(*) AS total_consultation_count, SUM(CASE WHEN consultation_status = 'RECEIVED' THEN 1 ELSE 0 END) AS received_count, SUM(CASE WHEN consultation_status = 'SCHEDULED' THEN 1 ELSE 0 END) AS scheduled_count, SUM(CASE WHEN consultation_status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_count, SUM(CASE WHEN consultation_status = 'CONVERTED' THEN 1 ELSE 0 END) AS converted_count, SUM(CASE WHEN consultation_status = 'CANCELED' THEN 1 ELSE 0 END) AS canceled_count, CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND((SUM(CASE WHEN consultation_status = 'CONVERTED' THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)) * 100, 2) END AS conversion_rate FROM consultation WHERE 1 = 1
AND created_at::DATE >= #{startDate}
AND created_at::DATE <= #{endDate}

SELECT COUNT(*) AS total_inquiry_count, SUM(CASE WHEN inquiry_status = 'WAITING' THEN 1 ELSE 0 END) AS waiting_count, SUM(CASE WHEN inquiry_status = 'ANSWERED' THEN 1 ELSE 0 END) AS answered_count FROM inquiry WHERE 1 = 1
AND created_at::DATE >= #{startDate}
AND created_at::DATE <= #{endDate}

SELECT t.treatment_id, t.treatment_name, COUNT(r.reservation_id) AS reservation_count FROM treatment t LEFT JOIN reservation r ON t.treatment_id = r.treatment_id
r.reservation_date >= #{startDate}
AND r.reservation_date <= #{endDate}
GROUP BY t.treatment_id, t.treatment_name ORDER BY reservation_count DESC, t.treatment_id
